head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
// 컴포넌트·전역 이름 조회(엔진 캐시 → 이름 그대로 실행 → mf_ 접두사 붙여 다시, 없으면 받은 id 문자열 반환). 2026-11
scwin.__getObj = function(id) {
	if (typeof id !== 'string') return id;
	var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
	if (!W.strictMode) id = id.replace(/mf_/g, '');
	if (C[U[id]]) return C[U[id]];
	var r; try { r = F(id); } catch (e) {}
	if (r == undefined && W.strictMode) {
		var P = W.strictModeFrame.id + '_';
		var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
		s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
		if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
	}
	return r == undefined ? id : r;
};
scwin.trigger1_onclick = function(e) {
	inputCalendar1.setDisabled(true);
};
scwin.trigger2_onclick = function(e) {
	inputCalendar1.setDisabled(false);
};
scwin.trigger3_onclick = function(e) {
	inputCalendar1.setPlaceholder("inputCalendar1 setPlaceholder API 적용");
};
scwin.trigger4_onclick = function(e) {
	inputCalendar2.setDisabled(true);
};
scwin.trigger5_onclick = function(e) {
	inputCalendar2.setDisabled(false);
};
scwin.trigger6_onclick = function(e) {
	inputCalendar2.setPlaceholder("inputCalendar2 setPlaceholder API 적용");
};
scwin.trigger7_onclick = function(e) {
	inputCalendar1.setReadOnly(true);
};
scwin.trigger8_onclick = function(e) {
	inputCalendar1.setReadOnly(false);
};
scwin.trigger9_onclick = function(e) {
	inputCalendar2.setReadOnly(true);
};
scwin.trigger10_onclick = function(e) {
	inputCalendar2.setReadOnly(false);
};
scwin.fireDbClick = function(node) {
	if (document.createEventObject) {
		node.fireEvent('ondblclick');
	} else if (document.createEvent) {
		var evt = document.createEvent('MouseEvents');
		evt.initEvent('dblclick', true, false);
		node.dispatchEvent(evt);
	} else if (typeof node.ondblclick == 'function') {
		node.ondblclick();
	}
};
scwin.Dbclick = function(id) {
	var el = scwin.__getDom($p.id + id);
	scwin.fireDbClick(el);
};
scwin.checkValue = function(el) {
	if (el == "" || el == null) {
		return true;
	} else {
		return false;
	}
};
scwin.checkVal = function() {
	return scwin.checkValue(scwin.__getObj('inputCalendar1_input').getAttribute('disabled'));
};
scwin.checkVal2 = function() {
	return scwin.checkValue(scwin.__getObj('inputCalendar1_input').getAttribute('readOnly'));
};
scwin.checkVal3 = function() {
	return scwin.checkValue(scwin.__getObj('inputCalendar2_input').getAttribute('disabled'));
};
scwin.checkVal4 = function() {
	return scwin.checkValue(scwin.__getObj('inputCalendar2_input').getAttribute('readOnly'));
};
